// RotMG death cue; source documented in audio-sources.md. Bundled for offline play.
(()=>{const data='';let buffer=null,loading=false;const unlock=soundUnlock,previous=playSound;soundUnlock=function(){unlock();if(soundContext&&!buffer&&!loading){loading=true;const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));soundContext.decodeAudioData(bytes.buffer).then(value=>buffer=value).catch(()=>{loading=false})}};playSound=function(name){if(name!=='defeat'||!buffer)return previous(name);if(!soundContext||soundContext.state!=='running'||document.hidden||soundSettings.muted||!soundSettings.master||!soundSettings.combat)return false;const now=soundContext.currentTime;if(now-(soundLast.get(name)??-Infinity)<1)return false;soundLast.set(name,now);const source=soundContext.createBufferSource();source.buffer=buffer;source.connect(soundChannels.combat);source.onended=()=>source.disconnect();source.start();return true};})();
